  looking_ahead = excluded.looking_ahead;

-- postpartum week 100: How much food does your toddler actually need? Portion sizes and appetite
insert into nourish_week_content
  (stage, week_number, trimester, phase_label, theme_title, mantra,
   why_it_matters, condition_notes, meat_fish_eggs_note, using_meals_note,
   days, reflection, looking_ahead)
values
  ('postpartum',
   100,
   NULL,
   'Phase 5 of 6 — Beyond the first year',
   'How much food does your toddler actually need? Portion sizes and appetite',
   '"Portion sizes for a toddler are much smaller than they look, and appetite can swing from day to day without anything being wrong — growth simply slows down after infancy. Offering the food is your job; how much your toddler eats, or whether they eat it at all, is theirs. Steady growth over weeks and months matters far more than what happens at any single meal."',
   'Toddler portions are usually much smaller than adult portions. A child-sized plate, the child''s own hand, or roughly one measuring tablespoon of each food for each year of age can be used as a starting guide — not as a target the child must finish. Begin with a manageable amount and offer more whenever your toddler shows that they are still hungry. It helps to separate two different ideas: how much to put on the plate at one sitting, which is small and specific, and how much your toddler eats across a whole day of meals and snacks, which adds up naturally and varies more than most parents assume. After the rapid growth of infancy, growth usually slows through the toddler years, and appetite may become smaller or less predictable. It is normal for a toddler to eat enthusiastically at one meal and very little at another, or to eat differently from one day to the next. Activity, sleep, illness, teething and growth spurts can all affect appetite. Look at the pattern over time rather than judging any single meal. A widely endorsed approach in pediatrics divides mealtime responsibility this way: you decide what food is offered, when, and where; your toddler decides how much of it to eat, and whether to eat it at all. This isn''t a formula proven to guarantee a specific weight or growth outcome — research on feeding styles is still limited. This responsive approach is recommended in child-feeding guidance because it respects hunger and fullness cues while keeping the caregiver responsible for what, when and where food is offered. Beginning with a small, manageable serving can make the plate feel less overwhelming. If your toddler finishes it or shows signs of hunger, offer more without hesitation. The aim is not to restrict food — it is to let hunger and fullness cues, rather than the amount placed on the plate, guide how much gets eaten. Using this shared menu These are family meal ideas: serve the mother an appropriate adult portion, and any medical-condition notes below apply to her, not the toddler — "if you''re still hungry" also refers to the mother. Several meals naturally include dairy or eggs. The amounts given for the toddler in the lunch and dinner lines are starting portions, not a ceiling — offer more if your toddler wants it. For breakfast and nourishment breaks, begin with a small child-sized serving — for example, part of an idli, dosa, paratha or roti, or a few spoonfuls in a small bowl. These are starting amounts only. Offer more whenever your toddler remains interested or shows hunger cues.',
   'A note on very limited eating or growth concerns: if your toddler eats a very narrow range of foods or avoids entire food groups but otherwise seems well and is growing normally, discuss it at a routine health visit. Contact your child''s healthcare professional sooner if your toddler is losing weight, has stopped gaining as expected, becomes distressed or appears to be in pain while eating, or repeatedly coughs, chokes or struggles to swallow. These signs deserve individual assessment rather than being treated as ordinary picky eating. If you manage diabetes: continue your prescribed meal, monitoring and medication schedule as usual — this week''s focus on your child''s portions and appetite doesn''t change what you do for yourself. If you manage high blood pressure: keep added salt, pickles, papad and packaged sauces within the limits advised for you. If you take thyroid medication: continue it exactly as prescribed — this week''s focus on your toddler''s portions doesn''t change your own treatment. A toddler who is generally well, is growing along their own curve and is offered foods from different food groups regularly is showing reassuring signs. Growth alone cannot confirm every nutrient need, so continue routine health visits and follow any locally recommended guidance on supplements, fortified foods or testing.',
   '——————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————— Where a meat, fish or egg option appears, it is optional — choose the vegetarian alternative freely. Cook them all the way through, keep chicken and mutton boneless and either finely shredded or finely minced with any bone fragments removed, and keep fish meticulously deboned and finely flaked; this week''s fish choice (basa) is optional too. These are simply variety, not a requirement — a toddler eating well from the vegetarian options alone is meeting the same portion and appetite principles this week describes. ———————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————',
   NULL,
   '[{"day_number": 1, "title": "Anchor", "notes": "Toddler portions are usually much smaller than adult portions. A child-sized plate, the child''s own hand, or roughly one measuring tablespoon of each food for each year of age can be used as a starting guide — not as a target the child must finish. Begin with a manageable amount and offer more whenever your toddler shows that they are still hungry. It helps to separate two different ideas: how much to put on the plate at one sitting, which is small and specific, and how much your toddler eats across a whole day of meals and snacks, which adds up naturally and varies more than most parents assume.", "breakfast_a": "Idli with a smooth, mild coconut chutney", "breakfast_b": "Idli with a fully cooked hard-boiled egg, finely mashed, on the side", "lunch_a": "2-3 tablespoons of rice with 2 tablespoons of moong dal and a tablespoon of soft-cooked spinach (palak), finely chopped", "lunch_b": "2-3 tablespoons of rice with 2 tablespoons of boneless, finely shredded chicken and a tablespoon of soft-cooked spinach (palak), finely chopped", "nourishment_break_a": "A small bowl of curd with mashed ripe watermelon, seeds removed", "nourishment_break_b": "A small bowl of dal with grated paneer and a pinch of black pepper", "dinner_a": "2-3 tablespoons of soft khichdi with a tablespoon of soft-cooked bottle gourd (lauki), finely chopped", "dinner_b": "2-3 tablespoons of soft khichdi with 2 tablespoons of boneless, finely shredded chicken and a tablespoon of soft-cooked bottle gourd (lauki), finely chopped", "still_hungry": "A little more of whatever was offered at this meal"}, {"day_number": 2, "title": "Appetite that comes and goes", "notes": "After the rapid growth of infancy, growth usually slows through the toddler years, and appetite may become smaller or less predictable. It is normal for a toddler to eat enthusiastically at one meal and very little at another, or to eat differently from one day to the next. Activity, sleep, illness, teething and growth spurts can all affect appetite. Look at the pattern over time rather than judging any single meal.", "breakfast_a": "Moong dal dosa with a smooth, mild mint chutney", "breakfast_b": "Moong dal dosa with a fully cooked hard-boiled egg, finely mashed, on the side", "lunch_a": "A small toddler portion of soft roti, torn into manageable pieces and moistened if needed, with chana dal and soft-cooked pumpkin, mashed", "lunch_b": "A small toddler portion of soft roti, torn into manageable pieces and moistened if needed, with boneless, finely shredded chicken and soft-cooked pumpkin, mashed Day 2 — continued", "nourishment_break_a": "A small bowl of curd with a few segments of mosambi (sweet lime), seeds and membrane removed", "nourishment_break_b": "A small bowl of dal with a fully cooked hard-boiled egg, finely chopped and folded through", "dinner_a": "2-3 tablespoons of rice with 2 tablespoons of masoor dal and a tablespoon of soft-cooked capsicum, finely chopped", "dinner_b": "2-3 tablespoons of rice with 2 tablespoons of a mild basa fish curry, fully cooked, meticulously deboned and finely flaked, and a tablespoon of soft-cooked capsicum, finely chopped", "still_hungry": "A small bowl of curd"}, {"day_number": 3, "title": "Who decides what, and who decides how much", "notes": "A widely endorsed approach in pediatrics divides mealtime responsibility this way: you decide what food is offered, when, and where; your toddler decides how much of it to eat, and whether to eat it at all. This isn''t a formula proven to guarantee a specific weight or growth outcome — research on feeding styles is still limited. This responsive approach is recommended in child-feeding guidance because it respects hunger and fullness cues while keeping the caregiver responsible for what, when and where food is offered. Pressure to finish food can make mealtimes more stressful and may reduce a child''s willingness to eat or accept that food. Calm encouragement and repeated, pressure-free exposure are more consistent with responsive feeding.", "breakfast_a": "Vegetable paratha with a smooth, mild mint chutney", "breakfast_b": "Vegetable paratha with a fully cooked hard-boiled egg, finely chopped, on the side", "lunch_a": "2-3 tablespoons of soft khichdi with a tablespoon of soft-cooked cabbage, finely chopped", "lunch_b": "2-3 tablespoons of soft khichdi with 2 tablespoons of a mild mutton keema, fully cooked, finely minced and free of bone fragments, and a tablespoon of soft-cooked cabbage, finely chopped", "nourishment_break_a": "A small bowl of curd with a few segments of orange, seeds and membrane removed, finely chopped or mashed", "nourishment_break_b": "A small bowl of dal with grated paneer and a pinch of ajwain (carom seed) powder", "dinner_a": "2-3 tablespoons of rice with 2 tablespoons of rajma dal, well mashed, and a tablespoon of soft-cooked beetroot", "dinner_b": "2-3 tablespoons of rice with 2 tablespoons of boneless, finely shredded chicken and a tablespoon of soft-cooked beetroot", "still_hungry": "A small bowl of dal"}, {"day_number": 4, "title": "Bigger isn''t better", "notes": "Beginning with a small, manageable serving can make the plate feel less overwhelming. If your toddler finishes it or shows signs of hunger, offer more without hesitation. The aim is not to restrict food — it is to let hunger and fullness cues, rather than the amount placed on the plate, guide how much gets eaten.", "breakfast_a": "Paneer paratha with a smooth, mild coriander chutney", "breakfast_b": "Paneer paratha with a fully cooked hard-boiled egg, finely chopped, on the side", "lunch_a": "A small toddler portion of soft roti, torn into manageable pieces and moistened if needed, with masoor dal and green beans, cooked until very soft and finely chopped", "lunch_b": "A small toddler portion of soft roti, torn into manageable pieces and moistened if needed, with boneless, finely shredded chicken and green beans, cooked until very soft and finely chopped", "nourishment_break_a": "A small bowl of curd with mashed ripe jamun, seeds removed", "nourishment_break_b": "A small bowl of dal with a fully cooked hard-boiled egg, finely mashed and folded through", "dinner_a": "2-3 tablespoons of soft khichdi with a tablespoon of soft-cooked ridge gourd (turai), finely chopped", "dinner_b": "2-3 tablespoons of soft khichdi with 2 tablespoons of a mild basa fish curry, fully cooked, meticulously deboned and finely flaked, and a tablespoon of soft-cooked ridge gourd (turai), finely chopped", "still_hungry": "A small bowl of curd"}, {"day_number": 5, "title": "Ordinary picky eating, and what''s worth a closer look", "notes": "Some pickiness, some days of eating very little, and a strong preference for familiar foods are all typical at this age, and usually settle with time and repeated, pressure-free exposure. It''s worth mentioning to your child''s doctor if your toddler avoids entire food groups rather than just some foods, shows real distress or anxiety around meals, has stopped gaining weight or is losing weight, or regularly coughs, chokes or struggles while eating — these go beyond ordinary picky eating and are worth a closer look rather than something to wait out.", "breakfast_a": "Jowar roti with a smooth, mild tamarind chutney", "breakfast_b": "Jowar roti with a fully cooked hard-boiled egg, finely chopped, on the side", "lunch_a": "2-3 tablespoons of rice with 2 tablespoons of moong dal and a tablespoon of soft-cooked bhindi, finely chopped", "lunch_b": "2-3 tablespoons of rice with 2 tablespoons of boneless, finely shredded chicken and a tablespoon of soft-cooked bhindi, finely chopped", "nourishment_break_a": "A small bowl of curd with mashed ripe guava, thoroughly deseeded", "nourishment_break_b": "A small bowl of dal with grated paneer and a pinch of turmeric", "dinner_a": "2-3 tablespoons of soft khichdi with a tablespoon of soft-cooked snake gourd, finely chopped", "dinner_b": "2-3 tablespoons of soft khichdi with 2 tablespoons of a mild mutton keema, fully cooked, finely minced and free of bone fragments, and a tablespoon of soft-cooked snake gourd, finely chopped", "still_hungry": "A small bowl of dal"}, {"day_number": 6, "title": "A gentle habit, not a performance", "notes": "Growth tracked over time at routine health visits tells you far more than any single meal or day. If your toddler is generally well, is growing along their own curve and is regularly offered foods from different food groups, those are reassuring signs. Continue routine health visits and any locally recommended guidance on fortified foods, supplements or testing, because growth alone cannot confirm every nutrient need. Using dessert, screens or praise to bargain for one more bite can teach a toddler to eat past fullness, or to want the reward more than the food — it''s a habit worth avoiding even when a meal feels like a struggle.", "breakfast_a": "Suji (semolina) uttapam with a smooth, mild curry leaf chutney", "breakfast_b": "Suji (semolina) uttapam with a fully cooked hard-boiled egg, finely mashed, on the side", "lunch_a": "A small toddler portion of soft roti, torn into manageable pieces and moistened if needed, with chana dal and soft-cooked cauliflower, finely chopped", "lunch_b": "A small toddler portion of soft roti, torn into manageable pieces and moistened if needed, with boneless, finely shredded chicken and soft-cooked cauliflower, finely chopped", "nourishment_break_a": "A small bowl of curd with mashed ripe banana", "nourishment_break_b": "A small bowl of dal with grated paneer and a pinch of amchur (dry mango powder)", "dinner_a": "2-3 tablespoons of rice with 2 tablespoons of masoor dal and a tablespoon of soft-cooked carrot, finely grated and cooked until soft", "dinner_b": "2-3 tablespoons of rice with 2 tablespoons of boneless, finely shredded chicken and a tablespoon of soft-cooked carrot, finely grated and cooked until soft", "still_hungry": "A little more of whatever was offered at this meal"}, {"day_number": 7, "title": "Reflection", "notes": "No forced choices today. Looking back at the week, did mealtimes feel calmer when you focused on what to offer rather than how much got eaten — and does your toddler''s growth over time, rather than any single meal, feel like the better thing to watch?", "breakfast_a": null, "breakfast_b": null, "lunch_a": null, "lunch_b": null, "nourishment_break_a": null, "nourishment_break_b": null, "dinner_a": null, "dinner_b": null, "still_hungry": null}]'::jsonb,
   'This week isn''t about a stricter portion rule — it''s about noticing that toddlers eat what they need over time, in their own rhythm, when pressure is taken out of the room.',
   'Next week continues Phase 5 with another piece of life beyond the first year — still grounded in the same idea: small, steady adjustments serve your child''s nourishment better than any single rule enforced all at once.')
on conflict (stage, week_number) do update set
  trimester = excluded.trimester,
